-- ===========================================================
-- MindMate 建表脚本（PostgreSQL 16）
--
-- 与达梦版本的差异：
--   1. 标识符不带引号且全小写，PostgreSQL 会把未加引号的标识符折叠成小写，
--      这样 MyBatis-Plus 生成的大写表名才能匹配。
--   2. VALUES、ROLE 是 PostgreSQL 关键字，实体用 @TableField("\"VALUES\"") 显式加引号，
--      因此这里也必须建成带引号的大写列名。
--   3. IDENTITY(1,1) -> GENERATED BY DEFAULT AS IDENTITY，允许迁移数据时显式写入主键。
--   4. CLOB -> TEXT，TINYINT -> SMALLINT，布尔语义的 MEMORY_ENABLED 用 BOOLEAN。
--   5. 去掉达梦专有的 STORAGE(ON "MAIN", CLUSTERBTR) 与 NOT CLUSTER PRIMARY KEY。
--
-- 执行：psql -h 127.0.0.1 -U mindmate -d mindmate -f schema.sql
-- ===========================================================

create table sys_user (
    user_id                bigint generated by default as identity primary key,
    phone_number           varchar(20)                           not null,
    username               varchar(50),
    avatar_url             varchar(255),
    personalized_signature varchar(255),
    email                  varchar(100),
    created_at             timestamp default current_timestamp   not null,
    updated_at             timestamp,
    last_login_at          timestamp,
    constraint uk_sys_user_phone unique (phone_number)
);

comment on table sys_user is '用户表';

create table task (
    id                  bigint generated by default as identity primary key,
    user_id             bigint                              not null,
    title               varchar(200)                        not null,
    description         text,
    status              smallint  default 0                 not null,
    priority            smallint  default 1                 not null,
    planned_date        date,
    due_at              timestamp,
    estimated_minutes   int,
    actual_minutes      int,
    started_at          timestamp,
    completed_at        timestamp,
    defer_count         int       default 0                 not null,
    first_planned_date  date,
    last_deferred_at    timestamp,
    source              smallint  default 1                 not null,
    created_at          timestamp default current_timestamp not null,
    updated_at          timestamp,
    deleted             smallint  default 0                 not null
);

comment on table task is '任务表（当前状态快照）';

create index idx_task_user_status_plan on task (user_id, status, planned_date);
create index idx_task_user_due on task (user_id, due_at);

create table task_event (
    id          bigint generated by default as identity primary key,
    task_id     bigint                                 not null,
    user_id     bigint                                 not null,
    event_type  varchar(32)                            not null,
    payload     text,
    occurred_at timestamp(3) default current_timestamp not null,
    created_at  timestamp    default current_timestamp not null
);

comment on table task_event is '任务事件流（不可变，行为历史的唯一事实来源）';

create index idx_task_event_task_time on task_event (task_id, occurred_at);
create index idx_task_event_user_type_time on task_event (user_id, event_type, occurred_at);

create table decision_preference (
    user_id          bigint primary key,
    personality      text,
    interests        text,
    "VALUES"         text,
    goals            text,
    decision_style   text,
    memory_enabled   boolean     default false            not null,
    created_at       timestamp   default current_timestamp not null,
    updated_at       timestamp   default current_timestamp not null
);

comment on table decision_preference is '用户明确填写的决策偏好，不从对话隐式提取';

create table decision_session (
    id         bigint generated by default as identity primary key,
    user_id    bigint                              not null,
    title      varchar(400)                        not null,
    created_at timestamp default current_timestamp not null,
    updated_at timestamp default current_timestamp not null
);

comment on table decision_session is '决策会话';

create index idx_dec_session_owner_time on decision_session (user_id, updated_at, id);

create table decision_message (
    id         bigint generated by default as identity primary key,
    session_id bigint                              not null,
    user_id    bigint                              not null,
    "ROLE"     varchar(16)                         not null,
    content    text                                not null,
    created_at timestamp default current_timestamp not null,
    constraint ck_dec_message_role check ("ROLE" in ('user', 'assistant'))
);

comment on table decision_message is '决策消息，仅在模型成功后同事务保存完整一轮';

create index idx_dec_message_owner_session on decision_message (user_id, session_id, id);

create table sys_quote (
    id         bigint generated by default as identity primary key,
    user_id    bigint                                not null,
    content    text,
    source     varchar(200),
    media_type smallint  default 0                   not null,
    media_url  varchar(500),
    created_at timestamp default current_timestamp   not null,
    deleted    smallint  default 0                   not null,
    constraint ck_sys_quote_media_type check (media_type in (0, 1, 2)),
    constraint ck_sys_quote_deleted check (deleted in (0, 1))
);

comment on table sys_quote is '经典语录，含可选图片或视频媒体';

create index idx_sys_quote_user_deleted_id on sys_quote (user_id, deleted, id);
